// Re-embeds public/assets/logo.jpg into netlify/functions/_lib/assets.js.
// Run after replacing the logo:  node scripts/build-assets.js
const fs = require("fs");
const logo = fs.readFileSync("public/assets/logo.jpg").toString("base64");
fs.writeFileSync("netlify/functions/_lib/assets.js",
  '// GENERATED by scripts/build-assets.js - embeds public/assets/logo.jpg so the certificate function needs no file access.\nmodule.exports = {\n  logo: "' + logo + '"\n};\n');
console.log("logo re-embedded");
